---@field LoopView                      	SuperScrollView.LoopListView2           
local UIBambooRewardDialog = Class("UIBambooRewardDialog")

function UIBambooRewardDialog:__init() 
    self._activityUuid = 0 
    self._activityId = 0               --当前活动id
    self._allReward = {}            --所有的奖励
end

function UIBambooRewardDialog:__delete()
    self._activityUuid = nil 
    self._activityId = nil
    self._allReward = nil
end

function UIBambooRewardDialog:Awake()
    GameUtils.RefreshTopGoods(Constants.UITypeIds.UIBambooRewardDialog)
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._activityUuid = checkNumber(argument.activityUuid)  
    if self._activityUuid == 0 then
        return
    end

    self._activityId = BambooUtils.GetActivityId(self._activityUuid)    --活动id
    if self._activityId == 0 then
        return
    end

    self:InitData()
    self:FillSelf()

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, 2592000, false, true) 
end

function UIBambooRewardDialog:InitData()
    self._allReward = {}

    local t = BambooUtils.GetAllReward(self._activityId)
    if not t then
        return
    end

    for k, v in pairs(t) do
        table.insert(self._allReward, {
            id = checkNumber(k),
            status = checkNumber(v)
        })
    end

    table.sort(self._allReward, function(a, b)
        if checkNumber(a.status) == checkNumber(b.status) then
            local fVo = BambooUtils.GetBambooIntegralRewardVo(a.id)
            local tVo = BambooUtils.GetBambooIntegralRewardVo(b.id)
            if fVo and tVo then
                return checkNumber(fVo.needNum) < checkNumber(tVo.needNum) 
            end
        else
            if checkNumber(a.status) == 1 then
                return true
            elseif checkNumber(b.status) == 1 then
                return false
            else
                return checkNumber(a.status) < checkNumber(b.status) 
            end
        end

        return false
    end)
end

function UIBambooRewardDialog:FillTime()
    local data = BambooQuestComponent:GetBambooActivityDojo(self._activityUuid)
    local num = checkNumber(data.closeTime)
    if num < 0 then
        num = 0
    end
    CfUtils.FillText(self.Text2, CfUtils.GetTimeHMS4(num))
end

function UIBambooRewardDialog:FillSelf()
    local vo = BambooUtils.GetBambooActivityVo(self._activityId)
    if not vo then
        return
    end
    CfUtils.FillImage(self.ImgBg, vo.sceneId)
    CfUtils.FillText(self.TexNumber, BambooUtils.GetChallengeCurrencySum())
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.BambooIntegralCurrency))
    self:FillTime()

    local scr = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
    if scr then
        scr:RefreshSelf(vo.cardId, nil, function(cardId)
            local GachaponUtils = import('Game.Gachapon.GachaponUtils')
            GachaponUtils.OpenDetail(cardId, { { id = Constants.UITypeIds.UIBambooRewardDialog } })

            --CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.CommonStylePreView, parameters = {skinId = vo.cardId}}, {{id = CS.Engine.UI.UIModule.CurrentScreen:LastDialog().Argument.id}, {id = Constants.UITypeIds.UIHomeView}})

            --KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, vo.cardId)
        end)
    end

    vo = CardConfMgr:GetInstance():GetCardByRefId(vo.cardId)
    self.BossDrawingNode:Execute(checkNumber(vo.defaultSkin))

    self.TaskList:InitListView(table.count(self._allReward), Bind(self, self.OnGetItemByIndex))

    SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyReward))
end

function UIBambooRewardDialog:OneKeyReward()
    local isHaveReard = BambooUtils.IsHaveCanDrawReward(self._activityId)
    if not isHaveReard then
        GameUtils.Toast(localize("无奖励领取"))
        return
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BambooQuestComponent)

    comp:ActivityQuestPtRewardReq(nil, self._activityUuid, function()
        self:InitData()
        GameUtils.ReloadData(self.TaskList, 0)
        GameUtils.ReloadData(self.TaskList, #self._allReward)
    end, self._activityId)
end

function UIBambooRewardDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIBambooRewardNode)
    local data = self._allReward[index + 1]
    if scr then
        scr:Refresh(data, function()
            
        end, self._activityUuid)
    end

    return cell
end

